# Let me look at the full rows with all 12 columns
with open('/app/resources/treasury_bulletin_1970_06_page_89.txt', 'r') as f:
    content = f.read()

import html.parser
class TableParser(html.parser.HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_td = False
        self.current_tag = None
        self.rows = []
        self.current_row = []
        self.current_data = ""

    def handle_starttag(self, tag, attrs):
        if tag == 'tr':
            self.current_row = []
        elif tag in ['td', 'th']:
            self.in_td = True

    def handle_endtag(self, tag):
        if tag in ['td', 'th']:
            self.current_row.append(self.current_data.strip())
            self.in_td = False
            self.current_data = ""
        elif tag == 'tr':
            if self.current_row:
                self.rows.append(self.current_row)

    def handle_data(self, data):
        if self.in_td:
            self.current_data += data

parser = TableParser()
parser.feed(content)

# Print rows with all columns
print("Monthly rows with all columns:")
for i, row in enumerate(parser.rows):
    if i >= 2 and i <= 37:  # Monthly data rows
        if row[0] in ['Jan.', 'Feb.', 'Mar.', 'Apr.', 'May', 'June', 'July', 'Aug.', 'Sept.', 'Oct.', 'Nov.', 'Dec.']:
            print(f"Row {i}: {row}")
